import { useSession } from "./lib/auth-client"
import NotificationPage from "./components/NotificationPage"
import AuthPage from "./components/AuthPage"

function App() {
  const { data: session, isPending } = useSession()

  if (isPending) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background">
        <div className="h-8 w-8 rounded-full border-2 border-border border-t-primary animate-[a-spin_0.6s_linear_infinite]" />
      </div>
    )
  }

  return (
    <div className="flex min-h-screen flex-col bg-background text-foreground">
      {session ? <NotificationPage user={session.user} /> : <AuthPage />}
    </div>
  )
}

export default App

import { useState } from "react"
import { signIn, signUp } from "../lib/auth-client"
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from "../components/ui/card"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Button } from "../components/ui/button"

export default function AuthPage() {
  const [mode, setMode] = useState<"sign-in" | "sign-up">("sign-in")
  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setLoading(true)

    try {
      if (mode === "sign-in") {
        const result = await signIn.email({ email, password })
        if (result.error) {
          setError(result.error.message ?? result.error.statusText)
        }
      } else {
        const result = await signUp.email({ name, email, password })
        if (result.error) {
          setError(result.error.message ?? result.error.statusText)
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred")
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center p-8">
      <Card className="w-full max-w-sm animate-[fadeSlideIn_0.4s_ease-out]">
        <CardHeader className="text-center">
          <CardTitle>{mode === "sign-in" ? "Sign In" : "Create Account"}</CardTitle>
          <CardDescription>Wave Notification Center</CardDescription>
        </CardHeader>

        <CardContent>
          <form className="flex flex-col gap-5" onSubmit={handleSubmit}>
            {error && (
              <div className="rounded-md bg-destructive/10 border border-destructive/25 px-4 py-3 text-sm font-medium text-destructive text-center">
                {error}
              </div>
            )}

            {mode === "sign-up" && (
              <div className="flex flex-col gap-1.5">
                <Label htmlFor="name">Name</Label>
                <Input
                  id="name"
                  type="text"
                  placeholder="Your name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  required
                  autoComplete="name"
                />
              </div>
            )}

            <div className="flex flex-col gap-1.5">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                autoComplete="email"
              />
            </div>

            <div className="flex flex-col gap-1.5">
              <Label htmlFor="password">Password</Label>
              <Input
                id="password"
                type="password"
                placeholder="Min 8 characters"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                minLength={8}
                autoComplete={mode === "sign-in" ? "current-password" : "new-password"}
              />
            </div>

            <Button type="submit" disabled={loading} className="w-full">
              {loading && (
                <span className="h-4 w-4 rounded-full border-2 border-white/30 border-t-white animate-[a-spin_0.6s_linear_infinite]" />
              )}
              {mode === "sign-in" ? "Sign In" : "Create Account"}
            </Button>
          </form>
        </CardContent>

        <CardFooter className="justify-center border-t pt-6">
          {mode === "sign-in" ? (
            <p className="text-sm text-muted-foreground">
              Don't have an account?{" "}
              <button
                className="font-semibold text-primary hover:text-primary/80 transition-colors bg-transparent border-none p-0 cursor-pointer"
                onClick={() => { setMode("sign-up"); setError(null) }}
              >
                Sign up
              </button>
            </p>
          ) : (
            <p className="text-sm text-muted-foreground">
              Already have an account?{" "}
              <button
                className="font-semibold text-primary hover:text-primary/80 transition-colors bg-transparent border-none p-0 cursor-pointer"
                onClick={() => { setMode("sign-in"); setError(null) }}
              >
                Sign in
              </button>
            </p>
          )}
        </CardFooter>
      </Card>
    </div>
  )
}

import { useEffect, useState, useRef, useCallback } from "react"
import { signOut } from "../lib/auth-client"
import type { Session } from "../lib/auth-client"
import { Card, CardContent } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"

interface Notification {
  id: string
  title: string
  message: string
  type: "info" | "warning" | "error"
  timestamp: string
  read: boolean
}

interface StandardResponse<T> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

function statusVariant(status: string): "default" | "secondary" | "destructive" {
  if (status === "connected") return "default"
  if (status === "disconnected") return "destructive"
  return "secondary"
}

function statusLabel(status: string): string {
  if (status === "connected") return "Live"
  if (status === "disconnected") return "Disconnected"
  return "Connecting"
}

export default function NotificationPage({ user }: { user: Session["user"] }) {
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [connectionStatus, setConnectionStatus] = useState<"connected" | "disconnected" | "connecting">("connecting")
  const eventSourceRef = useRef<EventSource | null>(null)
  const retryCountRef = useRef(0)

  const fetchInitial = useCallback(async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/notification/users/${user.id}/notifications?limit=50`)
      if (!response.ok) throw new Error(`HTTP ${response.status}`)
      const json: StandardResponse<Notification[]> = await response.json()
      setNotifications(json.data ?? [])
      setError(null)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load")
      setNotifications([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const connectSSE = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close()
    }

    setConnectionStatus("connecting")
    const es = new EventSource(`/api/notification/users/${user.id}/notifications/stream`)
    eventSourceRef.current = es

    es.onopen = () => {
      setConnectionStatus("connected")
      retryCountRef.current = 0
    }

    es.onmessage = (event) => {
      try {
        const parsed = JSON.parse(event.data)
        const items: Notification[] = parsed.result ?? parsed.data ?? []
        if (items.length > 0) {
          setNotifications((prev) => {
            const existing = new Set(prev.map((n) => n.id))
            const newItems = items.filter((n) => !existing.has(n.id))
            return [...newItems, ...prev].slice(0, 50)
          })
        }
      } catch {
        // ping or parse error - ignore
      }
    }

    es.onerror = () => {
      setConnectionStatus("disconnected")
      es.close()
      eventSourceRef.current = null

      const delay = Math.min(1000 * 2 ** retryCountRef.current, 30000)
      retryCountRef.current += 1
      setTimeout(connectSSE, delay)
    }
  }, [user.id])

  useEffect(() => {
    fetchInitial()
    connectSSE()
    return () => {
      if (eventSourceRef.current) eventSourceRef.current.close()
    }
  }, [fetchInitial, connectSSE])

  const dismissNotification = (id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id))
  }

  const markRead = (id: string) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    )
  }

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-2xl font-bold tracking-tight text-foreground">Notifications</h1>
        <div className="flex items-center gap-2">
          <Badge variant={statusVariant(connectionStatus)}>
            <span className={`mr-1.5 h-1.5 w-1.5 rounded-full ${
              connectionStatus === "connected" ? "bg-current animate-[pulseGlow_1.5s_ease-in-out_infinite]" :
              connectionStatus === "disconnected" ? "bg-current" :
              "bg-current animate-[pulseGlow_0.6s_ease-in-out_infinite]"
            }`} />
            {statusLabel(connectionStatus)}
          </Badge>
          <div className="flex flex-col items-end leading-tight px-3 border-r border-border">
            <span className="text-sm font-semibold text-foreground">{user.name}</span>
            <span className="text-xs text-muted-foreground">{user.email}</span>
          </div>
          <Button variant="outline" size="sm" onClick={fetchInitial}>
            Refresh
          </Button>
          <Button variant="destructive" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6">
        {loading && (
          <div className="flex flex-col gap-2">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} className="h-20 w-full rounded-lg" />
            ))}
          </div>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center justify-center gap-4 py-16 text-center">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10 border-2 border-destructive/30 text-destructive text-lg font-bold">
              !
            </div>
            <p className="text-muted-foreground">{error}</p>
            <Button variant="outline" onClick={fetchInitial}>
              Retry
            </Button>
          </div>
        )}

        {!loading && !error && notifications.length === 0 && (
          <div className="flex flex-col items-center justify-center gap-2 py-16 text-center">
            <h2 className="text-base font-semibold text-muted-foreground">No notifications</h2>
            <p className="text-sm text-muted-foreground/60">
              New notifications will appear here in real time.
            </p>
          </div>
        )}

        {!loading && !error && notifications.length > 0 && (
          <div className="flex flex-col gap-1.5">
            {notifications.map((n, idx) => (
              <Card
                key={n.id}
                className={`transition-colors animate-[fadeSlideIn_0.35s_ease-out_forwards] opacity-0 ${
                  n.read
                    ? "opacity-70 hover:opacity-100"
                    : "bg-accent-subtle border-primary/30"
                }`}
                style={{ animationDelay: `${idx * 0.03}s` }}
              >
                <CardContent className="flex gap-4 p-4">
                  <span
                    className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${
                      n.type === "info" ? "bg-primary" :
                      n.type === "warning" ? "bg-warning" :
                      "bg-error"
                    }`}
                  />
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-start gap-4 mb-0.5">
                      <h3 className={`text-sm ${n.read ? "font-medium" : "font-semibold"} text-foreground`}>
                        {n.title}
                      </h3>
                      <time className="shrink-0 text-xs text-muted-foreground/70 font-mono">
                        {new Date(n.timestamp).toLocaleTimeString(undefined, {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </time>
                    </div>
                    <p className="text-sm text-muted-foreground leading-relaxed line-clamp-2">
                      {n.message}
                    </p>
                    <div className="flex gap-2 mt-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      {!n.read && (
                        <Button variant="ghost" size="xs" onClick={() => markRead(n.id)}>
                          Mark read
                        </Button>
                      )}
                      <Button variant="ghost" size="xs" onClick={() => dismissNotification(n.id)}>
                        Dismiss
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Notification Center</span>
        <span>{notifications.length} notifications</span>
      </footer>
    </>
  )
}

