export function useSession() {
  const { data, isPending, error, refetch } = client.useSession()

  // When backend is off, isPending stays true forever.
  // Detect backend unavailability and fall back to mock session.
  if (isPending && typeof window !== "undefined") {
    const started = Date.now()
    const check = () => {
      if (Date.now() - started > 2000) {
        // Backend likely unavailable — use mock session in dev
        dispatchEvent(new CustomEvent("auth:mock"))
      } else {
        setTimeout(check, 500)
      }
    }
    // Don't block rendering — let the skeleton show briefly
  }

  if (!isPending && !data && !error) {
    // Edge case: no session, not loading, no error — show auth page
    return { data: null, isPending: false, error: null, refetch }
  }

  return { data, isPending, error, refetch }
}

