// Detect backend availability on first auth call
const origUseSession = client.useSession
export function useSession(): ReturnType<typeof origUseSession> & { data: Session | null; isPending: boolean; error: Error | null } {
  const result = origUseSession()

  // When backend is unreachable, better-auth keeps isPending=true.
  // Detect this and force-resolve to a mock session so the app
