import type { Config } from "tailwindcss"

const config: Config = {
  content: ["./src/**/*.{ts,tsx}"],
  theme: {
    extend: {}
  },
  plugins: [],
}
export default config

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

import index from "./index.html"

const BACKEND_PORT = 3000

Bun.serve({
  port: 5173,
  async fetch(req) {
    const url = new URL(req.url)

    if (url.pathname.startsWith("/api/")) {
      const target = new URL(url.pathname + url.search, `http://127.0.0.1:${BACKEND_PORT}`)
      return await fetch(target, {
        method: req.method,
        headers: req.headers,
        body: req.body,
      })
    }

    return new Response(await Bun.file("./dist/index.css").text(), {
      headers: { "Content-Type": "text/css" },
    })
  },
  routes: {
    "/*": index,
  },
})

import index from "./index.html"

const BACKEND = "http://127.0.0.1:3000"

Bun.serve({
  port: 5173,
  async fetch(req) {
    const url = new URL(req.url)
    if (!url.pathname.startsWith("/api/")) return

    const target = new URL(url.pathname + url.search, BACKEND)
    return await fetch(target, {
      method: req.method,
      headers: req.headers,
      body: req.body,
    })
  },
  routes: {
    "/*": index,
  },
})

