import { Routes, Route, Navigate } from "react-router-dom"
import { useSession } from "./lib/auth-client"
import { AuthPage } from "./components/AuthPage"
import { AccountPage } from "./pages/AccountPage"

function LoadingScreen() {
  return (
    <div className="flex min-h-screen items-center justify-center bg-white">
      <div className="flex flex-col items-center gap-4">
        <div className="h-8 w-8 animate-spin rounded-full border-2 border-gray-200 border-t-gray-400" />
        <p className="text-sm text-gray-500">Loading…</p>
      </div>
    </div>
  )
}

export function App() {
  const { data: session, isPending } = useSession()

  if (isPending) return <LoadingScreen />

  if (!session) return <AuthPage />

  return (
    <Routes>
      <Route path="/" element={<AccountPage />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  )
}

import { useState } from "react"
import { signIn, signUp } from "../lib/auth-client"

export function AuthPage() {
  const [mode, setMode] = useState<"sign-in" | "sign-up">("sign-in")
  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [error, setError] = useState("")
  const [loading, setLoading] = useState(false)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setError("")
    setLoading(true)
    try {
      const result =
        mode === "sign-in"
          ? await signIn.email({ email, password })
          : await signUp.email({ name, email, password })
      if (result.error) {
        setError(result.error.message || result.error.statusText || "Something went wrong")
      }
    } catch {
      setError("Network error — is the server running?")
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4">
      <form
        onSubmit={handleSubmit}
        className="w-full max-w-sm rounded-xl border border-gray-200 bg-white p-8 shadow-sm"
      >
        <h1 className="mb-1 text-2xl font-semibold tracking-tight text-gray-900">
          {mode === "sign-in" ? "Sign in" : "Create account"}
        </h1>
        <p className="mb-8 text-sm text-gray-500">
          {mode === "sign-in" ? "Welcome back" : "Get started with Wave"}
        </p>

        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
            {error}
          </div>
        )}

        {mode === "sign-up" && (
          <div className="mb-4">
            <label htmlFor="name" className="mb-1.5 block text-sm font-medium text-gray-700">
              Name
            </label>
            <input
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
              className="block w-full rounded-lg border border-gray-300 px-3 py-2 text-sm outline-none transition-colors focus:border-gray-400 focus:ring-1 focus:ring-gray-300"
            />
          </div>
        )}

        <div className="mb-4">
          <label htmlFor="email" className="mb-1.5 block text-sm font-medium text-gray-700">
            Email
          </label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className="block w-full rounded-lg border border-gray-300 px-3 py-2 text-sm outline-none transition-colors focus:border-gray-400 focus:ring-1 focus:ring-gray-300"
          />
        </div>

        <div className="mb-6">
          <label htmlFor="password" className="mb-1.5 block text-sm font-medium text-gray-700">
            Password
          </label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            minLength={8}
            className="block w-full rounded-lg border border-gray-300 px-3 py-2 text-sm outline-none transition-colors focus:border-gray-400 focus:ring-1 focus:ring-gray-300"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full rounded-lg bg-gray-900 px-4 py-2.5 text-sm font-medium text-white transition-colors hover:bg-gray-800 disabled:cursor-not-allowed disabled:opacity-50"
        >
          {loading ? "Please wait…" : mode === "sign-in" ? "Sign in" : "Create account"}
        </button>

        <p className="mt-6 text-center text-sm text-gray-500">
          {mode === "sign-in" ? (
            <>
              No account?{" "}
              <button
                type="button"
                onClick={() => { setMode("sign-up"); setError("") }}
                className="font-medium text-gray-900 underline-offset-2 hover:underline"
              >
                Sign up
              </button>
            </>
          ) : (
            <>
              Already have an account?{" "}
              <button
                type="button"
                onClick={() => { setMode("sign-in"); setError("") }}
                className="font-medium text-gray-900 underline-offset-2 hover:underline"
              >
                Sign in
              </button>
            </>
          )}
        </p>
      </form>
    </div>
  )
}

import { useEffect, useState } from "react"
import { useSession, signOut } from "../lib/auth-client"

interface WalletAccount {
  id: string
  name: string
  balance: string
  currency: string
}

export function AccountPage() {
  const { data: session, refetch } = useSession()
  const [accounts, setAccounts] = useState<WalletAccount[]>([])
  const [accountsLoading, setAccountsLoading] = useState(true)
  const [signingOut, setSigningOut] = useState(false)

  const user = session?.user

  useEffect(() => {
    if (!user) return
    fetch(`/api/wallet/users/${user.id}/accounts`)
      .then((r) => (r.ok ? r.json() : []))
      .then((data) => setAccounts(Array.isArray(data) ? data : data.data ?? []))
      .catch(() => setAccounts([]))
      .finally(() => setAccountsLoading(false))
  }, [user?.id])

  async function handleSignOut() {
    setSigningOut(true)
    await signOut()
    refetch()
  }

  const memberSince = user?.createdAt
    ? new Date(user.createdAt).toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
      })
    : "—"

  return (
    <div className="mx-auto max-w-2xl px-4 py-12">
      {/* Profile card */}
      <div className="mb-8 flex items-center gap-5">
        <div className="flex h-16 w-16 items-center justify-center rounded-full bg-gray-100 text-xl font-semibold text-gray-600">
          {user?.name?.charAt(0)?.toUpperCase() ?? "?"}
        </div>
        <div>
          <h1 className="text-xl font-semibold text-gray-900">{user?.name}</h1>
          <p className="text-sm text-gray-500">{user?.email}</p>
          <p className="text-xs text-gray-400">Member since {memberSince}</p>
        </div>
      </div>

      {/* Account details */}
      <section className="mb-8 rounded-xl border border-gray-200 bg-white p-6 shadow-sm">
        <h2 className="mb-4 text-base font-semibold text-gray-900">Details</h2>
        <dl className="space-y-3 text-sm">
          <div className="flex justify-between">
            <dt className="text-gray-500">User ID</dt>
            <dd className="font-mono text-gray-700">{user?.id}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-gray-500">Email verified</dt>
            <dd className="text-gray-700">
              {user?.emailVerified ? (
                <span className="text-green-600">Yes</span>
              ) : (
                <span className="text-amber-600">No</span>
              )}
            </dd>
          </div>
        </dl>
      </section>

      {/* Wallet accounts */}
      <section className="mb-8 rounded-xl border border-gray-200 bg-white p-6 shadow-sm">
        <h2 className="mb-4 text-base font-semibold text-gray-900">Wallet accounts</h2>
        {accountsLoading ? (
          <div className="space-y-3">
            {[1, 2].map((i) => (
              <div key={i} className="h-14 animate-pulse rounded-lg bg-gray-100" />
            ))}
          </div>
        ) : accounts.length === 0 ? (
          <p className="text-sm text-gray-400">No accounts yet</p>
        ) : (
          <ul className="divide-y divide-gray-100">
            {accounts.map((a) => (
              <li key={a.id} className="flex items-center justify-between py-3">
                <span className="text-sm font-medium text-gray-900">{a.name}</span>
                <span className="font-mono text-sm text-gray-600">
                  {a.balance} {a.currency}
                </span>
              </li>
            ))}
